// ===== Configuración: cambia solo estas tres líneas =====
const AVISOS = 'awayu-avisos-j614insb';  // tema de ntfy para avisos generales (cualquiera puede suscribirse; elige uno difícil de adivinar)
const SECRETO = '';                          // el mismo valor de N8N_SECRET en Vercel; vacío = no se comprueba la firma
const WEB = 'https://awayu-two.vercel.app';
// ========================================================

const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

if (SECRETO) {
  // n8n autoalojado necesita NODE_FUNCTION_ALLOW_BUILTIN=crypto para esta parte
  const crypto = require('crypto');
  const firma = 'sha256=' + crypto.createHmac('sha256', SECRETO).update(JSON.stringify(body)).digest('hex');
  if (headers['x-awayu-signature'] !== firma) throw new Error('Firma inválida: el evento no viene de Awayu');
}

const TIPOS = ['circulo_creado', 'aporte', 'garantia', 'pozo', 'plazo_cerca'];
if (!TIPOS.includes(body.type)) return [];
const d = body.data || {};
const circulo = String(body.circle || '');

// Fila para la tabla interna de n8n (Data table), sin Google Sheets
const fila = { tipo: body.type, circulo, datos: JSON.stringify(d), recibido: new Date().toISOString() };

// Cada círculo tiene su propio tema: AVISOS + '-' + primeros 10 caracteres del contrato, en minúsculas
const temaCirculo = (AVISOS + '-' + circulo.slice(0, 10)).toLowerCase().replace(/[^a-z0-9_-]/g, '');
const corto = (s) => (s ? String(s).slice(0, 4) + '…' + String(s).slice(-4) : '');
const enlace = d.link || (circulo ? WEB + '/?c=' + circulo : WEB);
const avisos = [];
if (body.type === 'circulo_creado') {
  avisos.push({ topic: AVISOS, title: 'Nuevo pasanaku en Awayu', message: (d.name || 'Pasanaku') + ' (' + (d.region || '—') + '): ' + (d.members ?? '?') + ' miembros, cuota ' + (d.amount ?? '?') + ' ' + (d.token || '') + '. Avisos del círculo: ntfy.sh/' + temaCirculo, tags: ['tada'], click: enlace });
}
if (body.type === 'pozo') {
  avisos.push({ topic: temaCirculo, title: 'Ronda ' + (d.round ?? '?') + ': pozo pagado', message: corto(d.to) + ' recibió ' + (d.amount ?? '?') + ' ' + (d.token || '') + '.', tags: ['moneybag'], click: enlace });
}
if (body.type === 'plazo_cerca') {
  avisos.push({ topic: temaCirculo, title: 'Se acerca el plazo de tu ronda', message: 'Quedan unas ' + (d.hoursLeft ?? '?') + ' horas para aportar ' + (d.amount ?? '') + ' ' + (d.token || '') + ' en la ronda ' + (d.round ?? '?') + '.', tags: ['alarm_clock'], priority: 4, click: enlace });
}
return [{ json: { fila, avisos } }];

// Saca los avisos que armó el primer nodo (pozo, plazo cerca o círculo nuevo); los demás eventos solo se guardan
const avisos = $('Validar y armar aviso').first().json.avisos || [];
return avisos.map((json) => ({ json }));

// Resume las filas de la tabla awayu_eventos: total, conteo por tipo y los últimos 50
const filas = $input.all().map((i) => i.json).filter((r) => r && r.tipo);
filas.sort((a, b) => String(b.recibido).localeCompare(String(a.recibido)));
const porTipo = {};
for (const r of filas) porTipo[r.tipo] = (porTipo[r.tipo] || 0) + 1;
const ultimos = filas.slice(0, 50).map((r) => { let datos = {}; try { datos = JSON.parse(r.datos || '{}'); } catch (e) {} return { tipo: r.tipo, circulo: r.circulo, datos, recibido: r.recibido }; });
return [{ json: { total: filas.length, porTipo, ultimos, consultado: new Date().toISOString() } }];
